trait ResetFpInitSnapshot {
    fn reset_for_fp_init(&mut self);
}
impl ResetFpInitSnapshot for od_testkit::v2::X87Snapshot {
    fn reset_for_fp_init(&mut self) {
        self.control_word = HexU64(0x037f);
        self.status_word = HexU64(0);
        self.tag_word = HexU64(0xffff);
        self.instruction_pointer = HexU64(0);
        self.data_pointer = HexU64(0);
        self.last_opcode = HexU64(0);
    }
}

#[test]
fn cr0_fp_init_fixtures_check_literal_state_transitions_and_denial() {
    use od_testkit::v2::Profile;

    assert_eq!(CR0_FP_INIT_FIXTURES.len(), 32);
    for bytes in CR0_FP_INIT_FIXTURES {
        let (input, result) = run(bytes, "interpreter", 0);
        assert_eq!(input.fixture.profile, Profile::LongCr0FpInitV1);
        let id = input.fixture.case_id.as_str();
        let bits = id
            .split("emts_")
            .nth(1)
            .and_then(|part| part.chars().next())
            .and_then(|c| c.to_digit(10))
            .unwrap_or(0) as u64;
        let initial_cr0 = input.fixture.initial_state.cr0.unwrap().get();
        let mut expected = input.fixture.initial_state.clone();
        let (exit, retired) = if id.starts_with("s2_25a_full_") {
            expected.cr0 = Some(HexU64(0x8001_0033));
            expected.gpr[0] = HexU64(0x8001_0033);
            expected.rflags = HexU64(0x0616);
            expected.rip = input.fixture.stop_rip.unwrap();
            expected.x87.as_mut().unwrap().reset_for_fp_init();
            (Outcome::StopAddress {}, 4)
        } else if id.starts_with("s2_25a_fninit_gate_") {
            if bits == 0 {
                expected.rip = input.fixture.stop_rip.unwrap();
                expected.x87.as_mut().unwrap().reset_for_fp_init();
                (Outcome::StopAddress {}, 1)
            } else {
                (Outcome::Exception {}, 0)
            }
        } else if id.starts_with("s2_25a_read_") {
            let cpl: u8 = input.fixture.cli_cpl.unwrap().into();
            if cpl == 0 {
                expected.gpr[0] = HexU64(initial_cr0);
                expected.rip = input.fixture.stop_rip.unwrap();
                (Outcome::StopAddress {}, 1)
            } else {
                (Outcome::Exception {}, 0)
            }
        } else if id.starts_with("s2_25a_write_") && !id.starts_with("s2_25a_write_fninit_") {
            let cpl: u8 = input.fixture.cli_cpl.unwrap().into();
            if cpl == 0 {
                expected.cr0 = Some(HexU64(0x8001_0033));
                expected.rip = input.fixture.stop_rip.unwrap();
                (Outcome::StopAddress {}, 1)
            } else {
                (Outcome::Exception {}, 0)
            }
        } else {
            let target = input.fixture.initial_state.gpr[0].get();
            expected.cr0 = Some(HexU64(target));
            if bits == 0 {
                expected.rip = input.fixture.stop_rip.unwrap();
                expected.x87.as_mut().unwrap().reset_for_fp_init();
                (Outcome::StopAddress {}, 2)
            } else {
                expected.rip = HexU64(input.fixture.initial_state.rip.get() + 3);
                (Outcome::Exception {}, 1)
            }
        };
        assert_eq!(result.outcome, exit, "{id}");
        assert_eq!(count(&result), retired, "{id}");
        assert_eq!(snapshot(&result).state, expected, "{id}");
        let (_, jit) = run(bytes, "jit", 4);
        assert!(matches!(jit.outcome, Outcome::Unsupported { .. }), "{id}");
        assert!(
            matches!(jit.snapshot, Observation::Unavailable { .. }),
            "{id}"
        );
    }
}

#[test]
fn cr0_fp_init_schema_rejects_neighbor_bytes_unfixed_cr0_and_selectors() {
    let mut fixture = Fixture::from_json(CR0_FP_INIT_FIXTURES[0]).unwrap().fixture;
    fixture.initial_state.cr0 = Some(HexU64(0x8001_0033 | (1 << 6)));
    assert!(fixture.validate().is_err(), "invalid CR0 was accepted");

    let mut fixture = Fixture::from_json(CR0_FP_INIT_FIXTURES[0]).unwrap().fixture;
    fixture.initial_state.cr0 = Some(HexU64(0x8001_0033));
    fixture.memory[0].initial_bytes_hex = "0f20c1".into();
    assert!(fixture.validate().is_err());

    let mut fixture = Fixture::from_json(CR0_FP_INIT_FIXTURES[0]).unwrap().fixture;
    fixture
        .initial_state
        .x87
        .as_mut()
        .unwrap()
        .instruction_selector = Some(HexU64(0x2b));
    assert!(fixture.validate().is_err());

    let mut fixture = Fixture::from_json(CR0_FP_INIT_FIXTURES[0]).unwrap().fixture;
    fixture.memory[0].permissions.read = true;
    assert!(fixture.validate().is_err());

    let mut fixture = Fixture::from_json(CR0_FP_INIT_FIXTURES[0]).unwrap().fixture;
    fixture.cli_cpl = Some(od_testkit::v2::CliCpl::Cpl3);
    fixture.expected_exit = ExpectedExit::Exception;
    assert!(
        fixture.validate().is_err(),
        "full sequence must require CPL0"
    );
}

#[test]
fn cr0_fp_init_result_validation_rejects_tampered_control_x87_and_definedness() {
    let (loaded, result) = run(CR0_FP_INIT_FIXTURES[0], "interpreter", 0);
    let mut changed_cr0 = result.clone();
    if let Observation::Available { value } = &mut changed_cr0.snapshot {
        value.state.cr0 = Some(HexU64(0x8001_0033 | 4));
    }
    assert!(changed_cr0.validate_for(&loaded).is_err());
    assert!(od_testkit::v2::compare(&loaded, &changed_cr0, &result).is_err());

    let mut changed_x87 = result.clone();
    if let Observation::Available { value } = &mut changed_x87.snapshot {
        value.state.x87.as_mut().unwrap().control_word = HexU64(0x027f);
    }
    assert!(changed_x87.validate_for(&loaded).is_err());
    assert!(od_testkit::v2::compare(&loaded, &changed_x87, &result).is_err());

    let mut changed_definedness = result;
    if let Observation::Available { value } = &mut changed_definedness.snapshot {
        value.rflags_defined = HexU64(od_isa::INTEGER_FLAGS);
    }
    assert!(changed_definedness.validate_for(&loaded).is_err());
    assert!(od_testkit::v2::compare(&loaded, &changed_definedness, &changed_definedness).is_err());
}

#[test]
fn cr4_fp_init_fixtures_use_mutable_controls_and_reject_tampering() {
    use od_testkit::v2::Profile;

    assert_eq!(CR4_FP_INIT_FIXTURES.len(), 6);
    for bytes in CR4_FP_INIT_FIXTURES {
        let (loaded, result) = run(bytes, "interpreter", 0);
        assert_eq!(loaded.fixture.profile, Profile::LongCr4FpInitV1);
        result
            .validate_for(&loaded)
            .unwrap_or_else(|error| panic!("{}: {error:?}", loaded.fixture.case_id));
        let (_, jit) = run(bytes, "jit", 4);
        assert!(matches!(jit.outcome, Outcome::Unsupported { .. }));
        assert!(matches!(jit.snapshot, Observation::Unavailable { .. }));

        let mut changed_cr4 = result.clone();
        if let Observation::Available { value } = &mut changed_cr4.snapshot {
            let current = value.state.cr4.unwrap().get();
            value.state.cr4 = Some(HexU64(current ^ (1 << 10)));
        }
        assert!(changed_cr4.validate_for(&loaded).is_err());
        assert!(od_testkit::v2::compare(&loaded, &changed_cr4, &result).is_err());
    }
    let mut invalid = od_testkit::v2::Fixture::from_json(CR4_FP_INIT_FIXTURES[0])
        .unwrap()
        .fixture;
    invalid.initial_state.cr4 = Some(HexU64(od_isa::execute::Cr4Profile::BASE | (1 << 11)));
    assert!(invalid.validate().is_err());

    let mut missing_cpl = od_testkit::v2::Fixture::from_json(CR4_FP_INIT_FIXTURES[0])
        .unwrap()
        .fixture;
    missing_cpl.cli_cpl = None;
    assert!(missing_cpl.validate().is_err());

    let mut invalid_composition = od_testkit::v2::Fixture::from_json(CR4_FP_INIT_FIXTURES[5])
        .unwrap()
        .fixture;
    invalid_composition.initial_state.cr0 =
        Some(HexU64(od_isa::execute::Cr0Profile::BASE | (1 << 3)));
    assert!(invalid_composition.validate().is_err());
}

#[test]
fn cr0_cr4_fp_init_composition_covers_all_initial_control_combinations_and_denies_jit() {
    use od_testkit::v2::Profile;

    assert_eq!(CR0_CR4_FP_INIT_FIXTURES.len(), 16);
    for bytes in CR0_CR4_FP_INIT_FIXTURES {
        let (loaded, result) = run(bytes, "interpreter", 0);
        assert_eq!(loaded.fixture.profile, Profile::LongCr0Cr4FpInitV1);
        result.validate_for(&loaded).unwrap();
        assert_eq!(count(&result), 8);
        let output = snapshot(&result);
        assert_eq!(
            output.state.cr0,
            Some(HexU64(od_isa::execute::Cr0Profile::BASE))
        );
        assert_eq!(
            output.state.cr4,
            Some(HexU64(
                loaded.fixture.initial_state.cr4.unwrap().get() | 0x600
            ))
        );
        assert_eq!(
            output.state.rip,
            HexU64(loaded.fixture.initial_state.rip.get() + 28)
        );
        assert_eq!(output.state.rflags, HexU64(0x0612));
        assert_eq!(output.rflags_defined, HexU64(0x0402));
        let (_, jit) = run(bytes, "jit", 4);
        assert!(matches!(jit.outcome, Outcome::Unsupported { .. }));
        assert!(matches!(jit.snapshot, Observation::Unavailable { .. }));

        let mut tampered = result.clone();
        if let Observation::Available { value } = &mut tampered.snapshot {
            value.state.cr4 = Some(HexU64(value.state.cr4.unwrap().get() ^ (1 << 10)));
        }
        assert!(tampered.validate_for(&loaded).is_err());
        assert!(od_testkit::v2::compare(&loaded, &tampered, &result).is_err());
    }
    let mut invalid = Fixture::from_json(CR0_CR4_FP_INIT_FIXTURES[0])
        .unwrap()
        .fixture;
    invalid.cli_cpl = Some(od_testkit::v2::CliCpl::Cpl1);
    invalid.expected_exit = ExpectedExit::Exception;
    assert!(
        invalid.validate().is_err(),
        "fixtures reserve the success profile for CPL0"
    );

    let mut changed_code = Fixture::from_json(CR0_CR4_FP_INIT_FIXTURES[0])
        .unwrap()
        .fixture;
    changed_code.memory[0].initial_bytes_hex.push_str("90");
    changed_code.memory[0].length += 1;
    changed_code.memory[0].comparison_mask_hex.push_str("ff");
    changed_code.stop_rip = Some(HexU64(changed_code.initial_state.rip.get() + 29));
    assert!(
        changed_code.validate().is_err(),
        "profile rejects trailing instructions"
    );

    let mut preserved_flags = Fixture::from_json(CR0_CR4_FP_INIT_FIXTURES[0])
        .unwrap()
        .fixture;
    preserved_flags.initial_state.rflags = HexU64(2);
    let bytes = preserved_flags.to_json().unwrap();
    let (loaded, result) = run(&bytes, "interpreter", 0);
    assert_eq!(snapshot(&result).state.rflags, HexU64(2));
    od_testkit::v2::compare(&loaded, &result, &result).unwrap_or_else(|error| panic!("{error:?}"));
}

#[test]
fn s2_39h_cr0_cr4_fxsave64_composition_is_strict_and_saves_literal_defined_fields() {
    use od_testkit::v2::Profile;

    let base = Fixture::from_json(CR0_CR4_FXSAVE64_COMPOSITION)
        .unwrap()
        .fixture;
    assert_eq!(base.profile, Profile::LongCr0Cr4FpInitFxsave64V1);
    let literal = od_testkit::v2::decode_bytes(
        include_str!("../../../tests/fixtures/x86/stage2/s2_39h_fxsave64_expected_image.hex")
            .trim()
            .replace('\n', "")
            .as_str(),
    )
    .unwrap();
    assert_eq!(literal.len(), 512);

    for cr0_pair in 0..4 {
        for cr4_pair in 0..4 {
            let mut input = base.clone();
            input.case_id = format!("s2_39h_cr0_{cr0_pair}_cr4_{cr4_pair}");
            input.initial_state.cr0 = Some(HexU64(
                od_isa::execute::Cr0Profile::BASE
                    | (((cr0_pair & 1) as u64) << 2)
                    | (((cr0_pair >> 1) as u64) << 3),
            ));
            input.initial_state.cr4 = Some(HexU64(
                od_isa::execute::Cr4Profile::BASE
                    | (((cr4_pair & 1) as u64) << 9)
                    | (((cr4_pair >> 1) as u64) << 10),
            ));
            let bytes = input.to_json().unwrap();
            let (loaded, result) = run(&bytes, "interpreter", 0);
            assert_eq!(count(&result), 9);
            let snapshot = snapshot(&result);
            assert_eq!(
                snapshot.state.cr0,
                Some(HexU64(od_isa::execute::Cr0Profile::BASE))
            );
            assert_eq!(snapshot.state.cr4, Some(HexU64(0x620)));
            assert_eq!(
                snapshot.state.rip,
                HexU64(loaded.fixture.initial_state.rip.get() + 33)
            );
            let save = snapshot
                .memory
                .iter()
                .find(|region| region.region_id == "save")
                .unwrap();
            let actual = od_testkit::v2::decode_bytes(&save.bytes_hex).unwrap();
            for (start, end) in [(0, 5), (6, 8), (8, 24), (24, 32), (160, 416)] {
                assert_eq!(
                    &actual[start..end],
                    &literal[start..end],
                    "save bytes {start}..{end}"
                );
            }
            for index in 0..8 {
                let start = 32 + index * 16;
                assert_eq!(&actual[start..start + 10], &literal[start..start + 10]);
            }
            let initial = od_testkit::v2::decode_bytes(
                &loaded
                    .fixture
                    .memory
                    .iter()
                    .find(|region| region.region_id == "save")
                    .unwrap()
                    .initial_bytes_hex,
            )
            .unwrap();
            assert_eq!(&actual[464..512], &initial[464..512]);
            result.validate_for(&loaded).unwrap();
            od_testkit::v2::compare(&loaded, &result, &result).unwrap();

            let (_, jit) = run(&bytes, "jit", 4);
            assert!(matches!(jit.outcome, Outcome::Unsupported { .. }));
            assert!(matches!(jit.snapshot, Observation::Unavailable { .. }));

            let mut changed_memory = result.clone();
            if let Observation::Available { value } = &mut changed_memory.snapshot {
                value
                    .memory
                    .iter_mut()
                    .find(|region| region.region_id == "save")
                    .unwrap()
                    .bytes_hex
                    .replace_range(48..50, "ff");
            }
            assert!(changed_memory.validate_for(&loaded).is_err());
            assert!(od_testkit::v2::compare(&loaded, &changed_memory, &result).is_err());

            let mut changed_tail = result.clone();
            if let Observation::Available { value } = &mut changed_tail.snapshot {
                let save = value
                    .memory
                    .iter_mut()
                    .find(|region| region.region_id == "save")
                    .unwrap();
                save.bytes_hex.replace_range(928..930, "00");
            }
            assert!(changed_tail.validate_for(&loaded).is_err());

            let mut changed_short = result.clone();
            if let Observation::Available { value } = &mut changed_short.snapshot {
                value
                    .memory
                    .iter_mut()
                    .find(|region| region.region_id == "save")
                    .unwrap()
                    .bytes_hex = "00".into();
            }
            assert!(changed_short.validate_for(&loaded).is_err());
        }
    }

    let mut alternate_mxcsr: serde_json::Value =
        serde_json::from_slice(CR0_CR4_FXSAVE64_COMPOSITION).unwrap();
    alternate_mxcsr["case_id"] = serde_json::json!("s2_39h_raw_mxcsr_1f80");
    alternate_mxcsr["initial_state"]["sse"]["mxcsr"] = serde_json::json!("0x0000000000001f80");
    let bytes = serde_json::to_vec(&alternate_mxcsr).unwrap();
    let (loaded, result) = run(&bytes, "interpreter", 0);
    result.validate_for(&loaded).unwrap();

    for mutate in [
        ("memory.code.initial_bytes_hex", serde_json::json!("90")),
        (
            "memory.save.guest_address",
            serde_json::json!("0x0000000000000670"),
        ),
        ("memory.save.permissions.execute", serde_json::json!(true)),
        ("instruction_budget", serde_json::json!(8)),
    ] {
        let mut value: serde_json::Value =
            serde_json::from_slice(CR0_CR4_FXSAVE64_COMPOSITION).unwrap();
        match mutate.0 {
            "memory.code.initial_bytes_hex" => value["memory"][0]["initial_bytes_hex"] = mutate.1,
            "memory.save.guest_address" => value["memory"][1]["guest_address"] = mutate.1,
            "memory.save.permissions.execute" => {
                value["memory"][1]["permissions"]["execute"] = mutate.1
            }
            "instruction_budget" => value["instruction_budget"] = mutate.1,
            _ => unreachable!(),
        }
        assert!(Fixture::from_json(&serde_json::to_vec(&value).unwrap()).is_err());
    }
}

#[test]
fn s2_39i_cr0_cr4_fxrstor64_composition_is_strict_and_restores_literal_image() {
    use od_testkit::v2::Profile;
    let base = Fixture::from_json(include_bytes!(
        "../../../tests/fixtures/x86/stage2/s2_39i_cr0_cr4_fxrstor64.case.json"
    ))
    .unwrap()
    .fixture;
    assert_eq!(base.profile, Profile::LongCr0Cr4FpInitFxrstor64V1);
    let literal = od_testkit::v2::decode_bytes(
        include_str!("../../../tests/fixtures/x86/stage2/s2_39i_fxrstor64_literal_image.hex")
            .trim()
            .replace('\n', "")
            .as_str(),
    )
    .unwrap();
    assert_eq!(literal.len(), 512);
    for cr0_pair in 0..4 {
        for cr4_pair in 0..4 {
            let mut input = base.clone();
            input.case_id = format!("s2_39i_cr0_{cr0_pair}_cr4_{cr4_pair}");
            input.initial_state.cr0 = Some(HexU64(
                od_isa::execute::Cr0Profile::BASE
                    | (((cr0_pair & 1) as u64) << 2)
                    | (((cr0_pair >> 1) as u64) << 3),
            ));
            input.initial_state.cr4 = Some(HexU64(
                od_isa::execute::Cr4Profile::BASE
                    | (((cr4_pair & 1) as u64) << 9)
                    | (((cr4_pair >> 1) as u64) << 10),
            ));
            let bytes = input.to_json().unwrap();
            let (loaded, result) = run(&bytes, "interpreter", 0);
            assert_eq!(count(&result), 9);
            result.validate_for(&loaded).unwrap();
            let state = &snapshot(&result).state;
            assert_eq!(state.cr0, Some(HexU64(od_isa::execute::Cr0Profile::BASE)));
            assert_eq!(
                state.cr4,
                Some(HexU64(od_isa::execute::Cr4Profile::BASE | 0x600))
            );
            assert_eq!(state.sse.as_ref().unwrap().mxcsr, HexU64(0x1f85));
            assert_eq!(state.x87.as_ref().unwrap().status_word, HexU64(0x2845));
            assert_eq!(
                state.x87.as_ref().unwrap().instruction_pointer,
                HexU64(0x8877_6655_4433_2211)
            );
            assert_eq!(
                state.x87.as_ref().unwrap().data_pointer,
                HexU64(0x1234_5678_9abc_def0)
            );
            assert_eq!(
                state.sse.as_ref().unwrap().xmm[0],
                od_testkit::memory::encode_bytes(&literal[160..176])
            );
            assert_eq!(
                snapshot(&result)
                    .memory
                    .iter()
                    .find(|region| region.region_id == "image")
                    .unwrap()
                    .bytes_hex,
                base.memory[1].initial_bytes_hex
            );
            od_testkit::v2::compare(&loaded, &result, &result).unwrap();
        }
    }
    let base_bytes =
        include_bytes!("../../../tests/fixtures/x86/stage2/s2_39i_cr0_cr4_fxrstor64.case.json");
    let (loaded, baseline) = run(base_bytes, "interpreter", 0);
    let mut forged_result = baseline.clone();
    if let Observation::Available { value: state } = &mut forged_result.snapshot {
        state.state.sse.as_mut().unwrap().xmm[0] = "ff".repeat(16);
    }
    assert!(forged_result.validate_for(&loaded).is_err());
    let mut forged_image = baseline.clone();
    if let Observation::Available { value: state } = &mut forged_image.snapshot {
        let image = state
            .memory
            .iter_mut()
            .find(|region| region.region_id == "image")
            .unwrap();
        image.bytes_hex.replace_range(0..2, "ff");
    }
    assert!(forged_image.validate_for(&loaded).is_err());

    let mut altered_ignored: serde_json::Value = serde_json::from_slice(base_bytes).unwrap();
    let mut ignored_bytes = od_testkit::v2::decode_bytes(
        altered_ignored["memory"][1]["initial_bytes_hex"]
            .as_str()
            .unwrap(),
    )
    .unwrap();
    for (offset, value) in [
        (5usize, 0x55),
        (28, 0x7f),
        (42, 0xe1),
        (416, 0x33),
        (480, 0x99),
    ] {
        ignored_bytes[offset] = value;
    }
    ignored_bytes[24..28].copy_from_slice(&0x1f80u32.to_le_bytes());
    altered_ignored["memory"][1]["initial_bytes_hex"] =
        serde_json::json!(od_testkit::memory::encode_bytes(&ignored_bytes));
    let (ignored_loaded, ignored_result) = run(
        &serde_json::to_vec(&altered_ignored).unwrap(),
        "interpreter",
        0,
    );
    ignored_result.validate_for(&ignored_loaded).unwrap();
    assert_eq!(
        snapshot(&ignored_result).state.x87,
        snapshot(&baseline).state.x87
    );
    let mut expected_sse = snapshot(&baseline).state.sse.clone().unwrap();
    expected_sse.mxcsr = HexU64(0x1f80);
    assert_eq!(snapshot(&ignored_result).state.sse, Some(expected_sse));
    assert_eq!(
        snapshot(&ignored_result)
            .memory
            .iter()
            .find(|region| region.region_id == "image")
            .unwrap()
            .bytes_hex,
        od_testkit::memory::encode_bytes(&ignored_bytes)
    );

    let (jit_loaded, jit_result) = run(base_bytes, "jit", 4);
    assert!(matches!(jit_result.outcome, Outcome::Unsupported { .. }));
    assert!(matches!(
        jit_result.snapshot,
        Observation::Unavailable { .. }
    ));
    assert_eq!(
        jit_loaded.fixture.profile,
        Profile::LongCr0Cr4FpInitFxrstor64V1
    );

    let mut invalid = serde_json::from_slice::<serde_json::Value>(include_bytes!(
        "../../../tests/fixtures/x86/stage2/s2_39i_cr0_cr4_fxrstor64.case.json"
    ))
    .unwrap();
    let image = invalid["memory"][1]["initial_bytes_hex"].as_str().unwrap();
    let mut image_bytes = od_testkit::v2::decode_bytes(image).unwrap();
    image_bytes[24..28].copy_from_slice(&0x1fc0u32.to_le_bytes());
    invalid["memory"][1]["initial_bytes_hex"] =
        serde_json::json!(od_testkit::memory::encode_bytes(&image_bytes));
    assert!(Fixture::from_json(&serde_json::to_vec(&invalid).unwrap()).is_err());
    for (field, replacement) in [
        ("instruction_budget", serde_json::json!(8)),
        (
            "initial_state.gpr.rbx",
            serde_json::json!("0x0000000000000630"),
        ),
        (
            "memory.code.bytes",
            serde_json::json!("0f20c04883e0f30f22c0dbe30f20e0480d000600000f22e0660f57c1480fae4b41"),
        ),
    ] {
        let mut tampered: serde_json::Value = serde_json::from_slice(base_bytes).unwrap();
        match field {
            "instruction_budget" => tampered[field] = replacement,
            "initial_state.gpr.rbx" => tampered["initial_state"]["gpr"][3] = replacement,
            "memory.code.bytes" => tampered["memory"][0]["initial_bytes_hex"] = replacement,
            _ => unreachable!(),
        }
        assert!(Fixture::from_json(&serde_json::to_vec(&tampered).unwrap()).is_err());
    }
    let mut forbidden_controls: serde_json::Value = serde_json::from_slice(base_bytes).unwrap();
    forbidden_controls["fxrstor64_cr0_controls"] =
        serde_json::json!({ "cr0_em": false, "cr0_ts": false });
    assert!(Fixture::from_json(&serde_json::to_vec(&forbidden_controls).unwrap()).is_err());
}

#[test]
fn s2_38e_runner_dispatches_fxrstor_minss_profile_and_denies_jit() {
    use od_testkit::v2::Profile;

    let cases: [(&[u8], u64, bool); 4] = [
        (
            include_bytes!(
                "../../../tests/fixtures/x86/stage2/s2_38e_fp_init_fxrstor64_minss.case.json"
            ),
            9,
            true,
        ),
        (
            include_bytes!("../../../tests/fixtures/x86/stage2/s2_38e_minss_masked_qnan.case.json"),
            10,
            false,
        ),
        (
            include_bytes!(
                "../../../tests/fixtures/x86/stage2/s2_38e_unmasked_subnormal.case.json"
            ),
            9,
            true,
        ),
        (
            include_bytes!("../../../tests/fixtures/x86/stage2/s2_38e_masked_subnormal.case.json"),
            10,
            false,
        ),
    ];

    for (bytes, retired, faults) in cases {
        let (loaded, result) = run(bytes, "interpreter", 0);
        assert_eq!(
            loaded.fixture.profile,
            Profile::LongCr0Cr4FpInitFxrstor64MinssV1
        );
        assert_eq!(count(&result), retired);
        assert_eq!(matches!(result.outcome, Outcome::Exception {}), faults);
        result.validate_for(&loaded).unwrap();
        od_testkit::v2::compare(&loaded, &result, &result).unwrap();
    }

    let (_, jit) = run(cases[0].0, "jit", 4);
    assert!(matches!(jit.outcome, Outcome::Unsupported { .. }));
    assert!(matches!(jit.snapshot, Observation::Unavailable { .. }));
}

#[test]
fn operand_size_prefixed_near_ret_keeps_qword_stack_semantics() {
    for (bytes, expected_code, expected_rip) in [
        (RET66, "66c3", 0x0010_0002),
        (RET66_IGNORED_REX, "4866c3", 0x0010_0003),
    ] {
        let (input, result) = run(bytes, "interpreter", 0);
        assert!(matches!(result.outcome, Outcome::StopAddress {}));
        assert_eq!(count(&result), 1);
        let observed = snapshot(&result);
        let mut expected_gpr = input.fixture.initial_state.gpr.clone();
        expected_gpr[4] = HexU64(0x0030_0088);
        assert_eq!(observed.state.gpr, expected_gpr);
        assert_eq!(observed.state.rip, HexU64(expected_rip));
        assert_eq!(observed.state.rflags, input.fixture.initial_state.rflags);
        assert_eq!(observed.rflags_defined, HexU64(0xcd7));
        assert_eq!(observed.memory.len(), 2);
        assert_eq!(observed.memory[0].bytes_hex, expected_code);
        assert_eq!(
            observed.memory[1].bytes_hex,
            input.fixture.memory[1].initial_bytes_hex
        );
    }
}

