#[test]
fn local_x87_m32_m64_stores_admit_historical_ze_and_keep_it_sticky() {
    for fixture in S2_31DX_M32_FIXTURES.into_iter().chain(S2_31DX_M64_FIXTURES) {
        let (input, result) = run(fixture, "interpreter", 0);
        assert!(matches!(result.outcome, Outcome::StopAddress {}));
        let output = snapshot(&result);
        let x87 = output.state.x87.as_ref().unwrap();
        let (store_hex, expected_status, expected_tag_word, expected_rip) = match input
            .fixture
            .case_id
            .as_str()
        {
            "s2_31dx_fst_m32fp_historical_ze" => ("ffff7f7f", 0x4504, 0xfffc, 0x0010_0002),
            "s2_31dx_fstp_m32fp_historical_ze" => ("ffff7fff", 0x4d04, 0xffff, 0x0010_0004),
            "s2_31dx_fst_m64fp_historical_ze" => ("ffffffffffffef7f", 0x4504, 0xfffc, 0x0010_0002),
            "s2_31dx_fstp_m64fp_historical_ze" => ("ffffffffffffefff", 0x4d04, 0xffff, 0x0010_0004),
            _ => unreachable!(),
        };
        assert_eq!(output.state.rip, HexU64(expected_rip));
        assert_eq!(count(&result), input.fixture.instruction_budget);
        assert_eq!(x87.status_word, HexU64(expected_status));
        assert_eq!(x87.status_word.get() & 0x0004, 0x0004);
        assert_eq!(x87.status_word.get() & 0x80c0, 0);
        assert_eq!(x87.tag_word, HexU64(expected_tag_word));
        assert_eq!(
            x87.registers,
            input.fixture.initial_state.x87.as_ref().unwrap().registers
        );
        assert_eq!(x87.data_pointer, HexU64(0x300004));
        assert_eq!(x87.instruction_pointer, input.fixture.initial_state.rip);
        let initial_rax = input.fixture.initial_state.gpr[0].get();
        assert_eq!(
            output.state.gpr[0].get(),
            if expected_tag_word == 0xffff {
                (initial_rax & !0xffff) | expected_status
            } else {
                initial_rax
            }
        );
        let stack = output
            .memory
            .iter()
            .find(|region| region.region_id == "stack")
            .unwrap();
        assert_eq!(&stack.bytes_hex[8..8 + store_hex.len()], store_hex);
        assert_eq!(
            input
                .fixture
                .initial_state
                .x87
                .as_ref()
                .unwrap()
                .status_word
                .get()
                & 4,
            4
        );

        let (_, jit) = run(fixture, "jit", 4);
        assert!(matches!(jit.outcome, Outcome::Unsupported { .. }));
        assert!(matches!(jit.snapshot, Observation::Unavailable { .. }));
        assert!(matches!(
            jit.instructions_executed,
            Observation::Unavailable { .. }
        ));
    }
}

