#[test]
fn cvttps2pi_mm0_xmm1_masked_profile_truncates_and_transitions_physical_mmx_state() {
    use od_testkit::v2::{ExpectedExit, Profile};

    let fixture = Fixture::from_json(CVTTPS2PI_MM0_XMM1).unwrap().fixture;
    assert_eq!(fixture.profile, Profile::LongCvttps2piRegisterMaskedV1);
    let values = [
        0x0000_0000u32, // +0
        0x8000_0000,    // -0
        0x3fe0_0000,    // +1.75, PE
        0xbfe0_0000,    // -1.75, PE
        0x3fc0_0000,    // +1.5 tie
        0xbfc0_0000,    // -1.5 tie
        0x4f00_0000,    // +2^31, IE
        0xcf00_0000,    // -2^31, valid exact boundary
        0x4eff_ffff,    // largest representable value below +2^31
        0xcf00_0001,    // immediately below -2^31, IE
        0x7fc0_0001,    // QNaN, IE
        0xffc0_0001,    // negative QNaN, IE
        0x7f80_0001,    // SNaN, IE
        0x7f80_0000,    // +infinity, IE
        0xff80_0000,    // -infinity, IE
        0x0000_0001,    // positive subnormal, zero with PE and no DE
        0x8000_0001,    // negative subnormal, zero with PE and no DE
    ];
    let exercise = |mut case: Fixture, lane0: u32, lane1: u32, rc: u64, top: u64| {
        case.case_id = format!("s2_37bh_{lane0:08x}_{lane1:08x}_rc{rc}_top{top}");
        let mut source = [0u8; 16];
        source[..4].copy_from_slice(&lane0.to_le_bytes());
        source[4..8].copy_from_slice(&lane1.to_le_bytes());
        source[8..].copy_from_slice(&0xdead_beef_cafe_babeu64.to_le_bytes());
        case.initial_state.sse.as_mut().unwrap().xmm[1] =
            source.iter().map(|byte| format!("{byte:02x}")).collect();
        case.initial_state.sse.as_mut().unwrap().mxcsr =
            HexU64((0x0000_1f82 & !(3 << 13)) | (rc << 13));
        case.initial_state.x87.as_mut().unwrap().status_word = HexU64((top << 11) | 0x0200);
        case.initial_state.x87.as_mut().unwrap().tag_word = HexU64(0xaaaa);
        let (input, result) = run(&case.to_json().unwrap(), "interpreter", 0);
        od_testkit::v2::compare(&input, &result, &result).unwrap();
        let Observation::Available { value: snapshot } = &result.snapshot else {
            panic!("snapshot")
        };
        let state = &snapshot.state;
        assert_eq!(
            state.sse.as_ref().unwrap().xmm,
            case.initial_state.sse.as_ref().unwrap().xmm
        );
        let x87 = state.x87.as_ref().unwrap();
        assert!(x87.registers[0].ends_with("ffff"));
        assert_eq!(x87.tag_word, HexU64(0));
        assert_eq!(x87.status_word.get() & !(7 << 11), 0x0200);
    };
    for rc in 0..4u64 {
        for (lane0, lane1) in values.iter().copied().zip(values.iter().copied().rev()) {
            exercise(fixture.clone(), lane0, lane1, rc, 3);
        }
        for top in 0..8u64 {
            exercise(fixture.clone(), values[2], values[7], rc, top);
        }
    }

    for (sse_available, cr0_em, cr4_osfxsr, cr0_ts, vector) in [
        (false, false, true, false, 6),
        (true, true, true, true, 6),
        (true, false, false, true, 6),
        (true, false, true, true, 7),
    ] {
        let mut case = fixture.clone();
        let controls = case.cvtpi2ps_memory_controls.as_mut().unwrap();
        controls.sse_available = sse_available;
        controls.cr0_em = cr0_em;
        controls.cr4_osfxsr = cr4_osfxsr;
        controls.cr0_ts = cr0_ts;
        case.expected_exit = ExpectedExit::Exception;
        let (input, result) = run(&case.to_json().unwrap(), "interpreter", 0);
        od_testkit::v2::compare(&input, &result, &result).unwrap();
        let Observation::Available { value: snapshot } = &result.snapshot else {
            panic!("snapshot")
        };
        let Observation::Available {
            value: Some(exception),
        } = &snapshot.exception
        else {
            panic!("exception")
        };
        assert_eq!(exception.vector, vector);
        let mut tampered_error_code = result.clone();
        let Observation::Available { value: snapshot } = &mut tampered_error_code.snapshot else {
            panic!("snapshot")
        };
        let Observation::Available {
            value: Some(exception),
        } = &mut snapshot.exception
        else {
            panic!("exception")
        };
        exception.error_code = Observation::Available { value: HexU64(123) };
        assert!(
            od_testkit::v2::compare(&input, &tampered_error_code, &tampered_error_code).is_err()
        );
    }

    for code in [
        "0f2cc0", "0f2cc2", "400f2cc1", "660f2cc1", "f30f2cc1", "0f2cc1c3",
    ] {
        let mut invalid = fixture.clone();
        invalid.memory[0].initial_bytes_hex = code.into();
        invalid.memory[0].length = (code.len() / 2) as u32;
        invalid.memory[0].comparison_mask_hex = "ff".repeat(code.len() / 2);
        invalid.stop_rip = Some(HexU64(
            invalid.initial_state.rip.get() + (code.len() / 2) as u64,
        ));
        assert!(invalid.validate().is_err(), "accepted {code}");
    }
    let mut pending = fixture.clone();
    pending.initial_state.x87.as_mut().unwrap().status_word = HexU64(1);
    assert!(pending.validate().is_err(), "accepted pending x87 state");
    let mut pm_unmasked = fixture.clone();
    pm_unmasked.initial_state.sse.as_mut().unwrap().mxcsr = HexU64(0x0000_efbf);
    assert!(pm_unmasked.validate().is_err(), "accepted PM=0");
    for backend in ["jit", "native"] {
        assert!(matches!(
            run(CVTTPS2PI_MM0_XMM1, backend, 4).1.outcome,
            Outcome::Unsupported { .. }
        ));
    }
    let (input, result) = run(CVTTPS2PI_MM0_XMM1, "interpreter", 0);
    let mut tampered = result.clone();
    let Observation::Available { value: snapshot } = &mut tampered.snapshot else {
        panic!("snapshot")
    };
    snapshot.state.x87.as_mut().unwrap().registers[0] = "00000000000000000000".into();
    assert!(od_testkit::v2::compare(&input, &result, &tampered).is_err());
}

#[test]
fn cvtps2pi_mm0_xmm1_masked_profile_rounds_and_transitions_physical_mmx_state() {
    use od_testkit::v2::{ExpectedExit, Profile};

    let fixture = Fixture::from_json(CVTPS2PI_MM0_XMM1).unwrap().fixture;
    assert_eq!(fixture.profile, Profile::LongCvtps2piRegisterMaskedV1);
    let values = [
        0x0000_0000u32, // +0
        0x8000_0000,    // -0
        0x3fe0_0000,    // +1.75, PE
        0xbfe0_0000,    // -1.75, PE
        0x3fc0_0000,    // +1.5 tie
        0xbfc0_0000,    // -1.5 tie
        0x4f00_0000,    // +2^31, IE
        0xcf00_0000,    // -2^31, valid exact boundary
        0x4eff_ffff,    // largest representable value below +2^31
        0xcf00_0001,    // immediately below -2^31, IE
        0x7fc0_0001,    // QNaN, IE
        0x7f80_0001,    // SNaN, IE
        0x7f80_0000,    // +infinity, IE
        0x0000_0001,    // positive subnormal, zero with PE and no DE
    ];
    let exercise = |mut case: Fixture,
                    lane0: u32,
                    lane1: u32,
                    rc: u64,
                    top: u64,
                    tags: u64,
                    old_sticky: u64| {
        case.case_id = format!(
            "s2_37bj_{lane0:08x}_{lane1:08x}_rc{rc}_top{top}_tags{tags:04x}_sticky{old_sticky:02x}"
        );
        let mut source = [0u8; 16];
        source[..4].copy_from_slice(&lane0.to_le_bytes());
        source[4..8].copy_from_slice(&lane1.to_le_bytes());
        source[8..].copy_from_slice(&0xdead_beef_cafe_babeu64.to_le_bytes());
        case.initial_state.sse.as_mut().unwrap().xmm[1] =
            source.iter().map(|byte| format!("{byte:02x}")).collect();
        case.initial_state.sse.as_mut().unwrap().mxcsr =
            HexU64((0x0000_1f80 & !(3 << 13)) | (rc << 13) | old_sticky);
        case.initial_state.x87.as_mut().unwrap().status_word = HexU64((top << 11) | 0x0200);
        case.initial_state.x87.as_mut().unwrap().tag_word = HexU64(tags);
        let (input, result) = run(&case.to_json().unwrap(), "interpreter", 0);
        od_testkit::v2::compare(&input, &result, &result).unwrap();
        let Observation::Available { value: snapshot } = &result.snapshot else {
            panic!("snapshot")
        };
        let state = &snapshot.state;
        assert_eq!(
            state.sse.as_ref().unwrap().xmm,
            case.initial_state.sse.as_ref().unwrap().xmm
        );
        let x87 = state.x87.as_ref().unwrap();
        assert!(x87.registers[0].ends_with("ffff"));
        assert_eq!(x87.tag_word, HexU64(0));
        assert_eq!(x87.status_word.get() & !(7 << 11), 0x0200);
    };
    for rc in 0..4u64 {
        for (lane0, lane1) in values.iter().copied().zip(values.iter().copied().rev()) {
            exercise(fixture.clone(), lane0, lane1, rc, 3, 0xaaaa, 0);
        }
        for top in 0..8u64 {
            for tags in [0x0000, 0x5555, 0xaaaa, 0xffff] {
                exercise(fixture.clone(), values[2], values[7], rc, top, tags, 0);
            }
        }
    }
    for old_sticky in [0, 1, 1 << 5, 1 | (1 << 5)] {
        exercise(fixture.clone(), 0, 0x8000_0000, 0, 0, 0x5555, old_sticky);
    }

    for (sse_available, cr0_em, cr4_osfxsr, cr0_ts, vector) in [
        (false, false, true, false, 6),
        (true, true, true, true, 6),
        (true, false, false, true, 6),
        (true, false, true, true, 7),
    ] {
        let mut case = fixture.clone();
        let controls = case.cvtps2pi_register_controls.as_mut().unwrap();
        controls.sse_available = sse_available;
        controls.cr0_em = cr0_em;
        controls.cr4_osfxsr = cr4_osfxsr;
        controls.cr0_ts = cr0_ts;
        case.expected_exit = ExpectedExit::Exception;
        let (input, result) = run(&case.to_json().unwrap(), "interpreter", 0);
        od_testkit::v2::compare(&input, &result, &result).unwrap();
        let Observation::Available { value: snapshot } = &result.snapshot else {
            panic!("snapshot")
        };
        let Observation::Available {
            value: Some(exception),
        } = &snapshot.exception
        else {
            panic!("exception")
        };
        assert_eq!(exception.vector, vector);
        let mut tampered_error_code = result.clone();
        let Observation::Available { value: snapshot } = &mut tampered_error_code.snapshot else {
            panic!("snapshot")
        };
        let Observation::Available {
            value: Some(exception),
        } = &mut snapshot.exception
        else {
            panic!("exception")
        };
        exception.error_code = Observation::Available { value: HexU64(123) };
        assert!(
            od_testkit::v2::compare(&input, &tampered_error_code, &tampered_error_code).is_err()
        );
    }

    for code in [
        "0f2dc0",
        "0f2dc2",
        "400f2dc1",
        "660f2dc1",
        "f30f2dc1",
        "0f2dc1c3",
        "c5f82dc1",
        "62f1ff082dc1",
    ] {
        let mut invalid = fixture.clone();
        invalid.memory[0].initial_bytes_hex = code.into();
        invalid.memory[0].length = (code.len() / 2) as u32;
        invalid.memory[0].comparison_mask_hex = "ff".repeat(code.len() / 2);
        invalid.stop_rip = Some(HexU64(
            invalid.initial_state.rip.get() + (code.len() / 2) as u64,
        ));
        assert!(invalid.validate().is_err(), "accepted {code}");
    }
    let mut pending = fixture.clone();
    pending.initial_state.x87.as_mut().unwrap().status_word = HexU64(1);
    assert!(pending.validate().is_err(), "accepted pending x87 state");
    let mut foreign_controls = fixture.clone();
    foreign_controls.cvtpi2ps_memory_controls = foreign_controls.cvtps2pi_register_controls;
    assert!(
        foreign_controls.validate().is_err(),
        "accepted CVTPI2PS controls on CVTPS2PI"
    );
    let mut malformed_json: serde_json::Value = serde_json::from_slice(CVTPS2PI_MM0_XMM1).unwrap();
    malformed_json["cvtpi2ps_memory_controls"] =
        malformed_json["cvtps2pi_register_controls"].clone();
    let malformed_json = serde_json::to_vec(&malformed_json).unwrap();
    assert!(
        Fixture::from_json(&malformed_json).is_err(),
        "load accepted CVTPI2PS controls on CVTPS2PI"
    );
    let mut pm_unmasked = fixture.clone();
    pm_unmasked.initial_state.sse.as_mut().unwrap().mxcsr = HexU64(0x0000_efbf);
    assert!(pm_unmasked.validate().is_err(), "accepted PM=0");
    for backend in ["jit", "native"] {
        assert!(matches!(
            run(CVTPS2PI_MM0_XMM1, backend, 4).1.outcome,
            Outcome::Unsupported { .. }
        ));
    }
    let (input, result) = run(CVTPS2PI_MM0_XMM1, "interpreter", 0);
    let mut tampered = result.clone();
    let Observation::Available { value: snapshot } = &mut tampered.snapshot else {
        panic!("snapshot")
    };
    snapshot.state.x87.as_mut().unwrap().registers[0] = "00000000000000000000".into();
    assert!(od_testkit::v2::compare(&input, &result, &tampered).is_err());
}

