#[test]
fn ucomiss_m32_invalid_only_covers_nan_mask_osxmmexcpt_sticky_matrix() {
    use od_testkit::v2::Profile;

    let base = Fixture::from_json(UCOMISS_M32_INVALID_FINITE)
        .unwrap()
        .fixture;
    assert_eq!(base.profile, Profile::LongUcomissMemoryInvalidRaxV1);
    assert_eq!(base.memory[0].initial_bytes_hex, "0f2e00");
    let encode_u32 = |value: u32| {
        value
            .to_le_bytes()
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>()
    };
    let cases = [
        (0x7fc1_2345u32, 0x3f80_0000u32, false, "qnan_lhs"),
        (0x3f80_0000, 0x7fc1_2345, false, "qnan_memory"),
        (0x7f81_2345, 0x3f80_0000, true, "snan_lhs"),
        (0x3f80_0000, 0x7f81_2345, true, "snan_memory"),
    ];
    let mut case_index = 0;
    for (lhs, rhs, signals_ie, stem) in cases {
        for im in [false, true] {
            for osxmmexcpt in [false, true] {
                for old_sticky in 0..64u64 {
                    let mut case = base.clone();
                    case.case_id = format!(
                        "s2_38v_{stem}_im{}_os{}_sticky{old_sticky:02x}",
                        u8::from(im),
                        u8::from(osxmmexcpt)
                    );
                    let xmm0 = &mut case.initial_state.sse.as_mut().unwrap().xmm[0];
                    xmm0.replace_range(0..8, &encode_u32(lhs));
                    case.memory[1].initial_bytes_hex = encode_u32(rhs);
                    case.initial_state.sse.as_mut().unwrap().mxcsr =
                        HexU64(0x1f00 | (u64::from(im) << 7) | old_sticky);
                    case.ucomiss_memory_invalid_rax_controls
                        .as_mut()
                        .unwrap()
                        .cr4_osxmmexcpt = osxmmexcpt;
                    let fault = signals_ie && !im;
                    case.expected_exit = if fault {
                        ExpectedExit::Exception
                    } else {
                        ExpectedExit::StopAddress
                    };
                    let json = case.to_json().unwrap();
                    let (input, result) = run(&json, "interpreter", 0);
                    od_testkit::v2::compare(&input, &result, &result).unwrap();
                    if fault {
                        assert!(matches!(result.outcome, Outcome::Exception {}));
                    } else {
                        assert!(matches!(result.outcome, Outcome::StopAddress {}));
                    }
                    let snapshot = match &result.snapshot {
                        Observation::Available { value } => value,
                        other => panic!("unexpected UCOMISS invalid-only snapshot: {other:?}"),
                    };
                    assert_eq!(
                        snapshot.state.sse.as_ref().unwrap().mxcsr.get() & 0x3f,
                        old_sticky | u64::from(signals_ie),
                        "{stem}, IM={im}, OSXMMEXCPT={osxmmexcpt}, sticky={old_sticky:#x}"
                    );
                    case_index += 1;
                }
            }
        }
    }
    assert_eq!(case_index, 1024);

    for (lhs, rhs, expected_flags, label) in [
        (0x4000_0000u32, 0x3f80_0000u32, 0, "finite_greater"),
        (0xbf80_0000, 0x3f80_0000, 1, "finite_less"),
        (0x3f80_0000, 0x3f80_0000, 1 << 6, "finite_equal"),
        (0x0000_0000, 0x8000_0000, 1 << 6, "signed_zero_equal"),
        (0x7f80_0000, 0x3f80_0000, 0, "positive_infinity_greater"),
        (0xff80_0000, 0xbf80_0000, 1, "negative_infinity_less"),
    ] {
        let mut case = base.clone();
        case.case_id = format!("s2_38v_{label}");
        case.initial_state.sse.as_mut().unwrap().xmm[0].replace_range(0..8, &encode_u32(lhs));
        case.memory[1].initial_bytes_hex = encode_u32(rhs);
        case.initial_state.sse.as_mut().unwrap().mxcsr = HexU64(0x1f80);
        let json = case.to_json().unwrap();
        let (input, result) = run(&json, "interpreter", 0);
        od_testkit::v2::compare(&input, &result, &result).unwrap();
        let observed = snapshot(&result);
        assert_eq!(
            observed.state.rflags.get() & 0x45,
            expected_flags,
            "{label}"
        );
        assert_eq!(
            observed.state.rip.get(),
            base.stop_rip.unwrap().get(),
            "{label}"
        );
    }

    for (lhs, rhs) in [(0x7fc1_2345u32, 0x7f81_2345u32), (0x7f81_2345, 0x7fc1_2345)] {
        let mut case = base.clone();
        case.case_id = format!("s2_38v_qnan_snan_{lhs:08x}_{rhs:08x}");
        case.initial_state.sse.as_mut().unwrap().xmm[0].replace_range(0..8, &encode_u32(lhs));
        case.memory[1].initial_bytes_hex = encode_u32(rhs);
        case.initial_state.sse.as_mut().unwrap().mxcsr = HexU64(0x1f00);
        case.ucomiss_memory_invalid_rax_controls
            .as_mut()
            .unwrap()
            .cr4_osxmmexcpt = true;
        case.expected_exit = ExpectedExit::Exception;
        let json = case.to_json().unwrap();
        let (input, result) = run(&json, "interpreter", 0);
        od_testkit::v2::compare(&input, &result, &result).unwrap();
        assert!(matches!(result.outcome, Outcome::Exception {}));
    }

    for fixture in [
        UCOMISS_M32_INVALID_FINITE,
        UCOMISS_M32_INVALID_QNAN_PRIOR_IE,
        UCOMISS_M32_INVALID_SNAN_MASKED,
        UCOMISS_M32_INVALID_SNAN_XM,
        UCOMISS_M32_INVALID_SNAN_UD,
        UCOMISS_M32_INVALID_SUBNORMAL_SNAN,
    ] {
        let expected_exit = if fixture == UCOMISS_M32_INVALID_SUBNORMAL_SNAN {
            4
        } else {
            0
        };
        let (input, result) = run(fixture, "interpreter", expected_exit);
        if expected_exit == 0 {
            od_testkit::v2::compare(&input, &result, &result).unwrap();
        }
    }
    assert!(matches!(
        run(UCOMISS_M32_INVALID_FINITE, "jit", 4).1.outcome,
        Outcome::Unsupported { .. }
    ));
    assert!(matches!(
        run(UCOMISS_M32_INVALID_FINITE, "native", 4).1.outcome,
        Outcome::Unsupported { .. }
    ));

    let mut malformed = base.clone();
    malformed.initial_state.sse.as_mut().unwrap().mxcsr = HexU64(0x0f80);
    assert!(malformed.validate().is_err(), "DM/PM masks must be set");
    malformed = base.clone();
    malformed.initial_state.sse.as_mut().unwrap().mxcsr = HexU64(0x9f80);
    assert!(malformed.validate().is_err(), "FTZ must be clear");
    malformed = base.clone();
    malformed.ucomiss_memory_rax_controls = Some(od_testkit::v2::UcomissMemoryRaxControlSnapshot {
        sse_available: true,
        cr0_em: false,
        cr0_ts: false,
        cr4_osfxsr: true,
    });
    assert!(
        malformed.validate().is_err(),
        "old-profile controls are foreign"
    );
    malformed = base.clone();
    malformed.memory[1].permissions.write = true;
    assert!(
        malformed.validate().is_err(),
        "data mapping must be read-only"
    );

    let (input, result) = run(UCOMISS_M32_INVALID_SNAN_XM, "interpreter", 0);
    let mut tampered = result.clone();
    if let Observation::Available { value } = &mut tampered.snapshot {
        value
            .ucomiss_memory_invalid_rax_controls
            .as_mut()
            .unwrap()
            .cr4_osxmmexcpt = false;
    }
    assert!(tampered.validate_for(&input).is_err());

    let (input, result) = run(UCOMISS_M32_INVALID_FINITE, "interpreter", 0);
    let mut backend_tampered = result.clone();
    backend_tampered.backend = Backend::Jit;
    assert!(backend_tampered.validate_for(&input).is_err());

    for mutation in 0..5 {
        let mut tampered = result.clone();
        match mutation {
            0 => {
                tampered.instructions_executed = Observation::Available { value: HexU64(0) };
            }
            1 => {
                let state = &mut snapshot_mut(&mut tampered).state;
                state.rip = HexU64(state.rip.get() + 1);
            }
            2 => {
                let state = &mut snapshot_mut(&mut tampered).state;
                state.rflags = HexU64(state.rflags.get() ^ 1);
            }
            3 => {
                let state = &mut snapshot_mut(&mut tampered).state;
                state.gpr[1] = HexU64(state.gpr[1].get() ^ 1);
            }
            _ => {
                let state = &mut snapshot_mut(&mut tampered).state;
                state.sse.as_mut().unwrap().xmm[0].replace_range(0..2, "ff");
            }
        }
        assert!(
            tampered.validate_for(&input).is_err(),
            "mutation {mutation}"
        );
    }
}

#[test]
fn cmpss_m32_memory_covers_predicates_nan_priority_and_denies_other_backends() {
    let fixture = Fixture::from_json(CMPSS_M32_MEMORY_RAX).unwrap().fixture;
    let truth = [
        [false, false, true, false],
        [false, true, false, false],
        [false, true, true, false],
        [false, false, false, true],
        [true, true, false, true],
        [true, false, true, true],
        [true, false, false, true],
        [true, true, true, false],
    ];
    let relations = [
        (0x4000_0000u32, 0x3f80_0000u32), // greater
        (0x3f80_0000, 0x4000_0000),       // less
        (0x0000_0000, 0x8000_0000),       // equal signed zero
        (0x7fc1_2345, 0x3f80_0000),       // unordered QNaN
    ];
    let encode_u32 = |value: u32| {
        value
            .to_le_bytes()
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>()
    };
    let decode_u32 = |hex: &str| {
        let bytes = (0..4)
            .map(|i| u8::from_str_radix(&hex[i * 2..i * 2 + 2], 16).unwrap())
            .collect::<Vec<_>>();
        u32::from_le_bytes(bytes.try_into().unwrap())
    };
    let old_sticky = [0u64, 1, 2, 3];
    let mut comparisons = 0usize;
    for predicate in 0u8..8 {
        for (relation, (left, right)) in relations.iter().copied().enumerate() {
            for rc in 0..4u32 {
                for ftz in [false, true] {
                    for old in old_sticky {
                        let mut case = fixture.clone();
                        case.case_id =
                            format!("s2_37cs_p{predicate}_r{relation}_rc{rc}_ftz{ftz}_old{old}");
                        case.memory[0].initial_bytes_hex = format!("f30fc200{predicate:02x}");
                        case.memory[0].comparison_mask_hex = "ff".repeat(5);
                        case.initial_state.sse.as_mut().unwrap().xmm[0] =
                            format!("{}{}", encode_u32(left), "010000000000f07f01000000");
                        case.initial_state.sse.as_mut().unwrap().mxcsr =
                            HexU64(0x0180 | old | (u64::from(rc) << 13) | (u64::from(ftz) << 15));
                        case.memory[1].initial_bytes_hex = encode_u32(right);
                        let (input, result) = run(&case.to_json().unwrap(), "interpreter", 0);
                        od_testkit::v2::compare(&input, &result, &result).unwrap();
                        let snapshot = match &result.snapshot {
                            Observation::Available { value } => value,
                            other => panic!("unexpected CMPSS snapshot: {other:?}"),
                        };
                        let output = decode_u32(&snapshot.state.sse.as_ref().unwrap().xmm[0]);
                        assert_eq!(
                            output,
                            if truth[usize::from(predicate)][relation] {
                                u32::MAX
                            } else {
                                0
                            }
                        );
                        let qnan_signaling_predicate = matches!(predicate, 1 | 2 | 5 | 6);
                        let raised_ie = relation == 3 && qnan_signaling_predicate;
                        assert_eq!(
                            snapshot.state.sse.as_ref().unwrap().mxcsr.get(),
                            0x0180
                                | old
                                | u64::from(raised_ie)
                                | (u64::from(rc) << 13)
                                | (u64::from(ftz) << 15)
                        );
                        assert_eq!(snapshot.state.rflags.get(), case.initial_state.rflags.get());
                        comparisons += 1;
                    }
                }
            }
        }
    }

    // QNaN never adds DE, while SNaN raises IE for every predicate; a numeric
    // subnormal raises DE only when neither operand is NaN.
    for (index, (left, right, generated)) in [
        (0x7fc1_2345, 1, 0),
        (1, 0x7fc1_2345, 0),
        (0x7f81_2345, 1, 1),
        (1, 0x7f81_2345, 1),
        (1, 0x3f80_0000, 2),
        (0x3f80_0000, 1, 2),
    ]
    .into_iter()
    .enumerate()
    {
        for predicate in 0u8..8 {
            let mut case = fixture.clone();
            case.case_id = format!("s2_37cs_priority_{index}_p{predicate}");
            case.memory[0].initial_bytes_hex = format!("f30fc200{predicate:02x}");
            case.memory[0].comparison_mask_hex = "ff".repeat(5);
            case.initial_state.sse.as_mut().unwrap().xmm[0] =
                format!("{}{}", encode_u32(left), "010000000000f07f01000000");
            case.initial_state.sse.as_mut().unwrap().mxcsr = HexU64(0x0180);
            case.memory[1].initial_bytes_hex = encode_u32(right);
            let (input, result) = run(&case.to_json().unwrap(), "interpreter", 0);
            od_testkit::v2::compare(&input, &result, &result).unwrap();
            let snapshot = match &result.snapshot {
                Observation::Available { value } => value,
                other => panic!("unexpected CMPSS snapshot: {other:?}"),
            };
            let nan = (left & 0x7f80_0000 == 0x7f80_0000 && left & 0x007f_ffff != 0)
                || (right & 0x7f80_0000 == 0x7f80_0000 && right & 0x007f_ffff != 0);
            let signaling = [left, right].into_iter().any(|bits| {
                bits & 0x7f80_0000 == 0x7f80_0000
                    && bits & 0x007f_ffff != 0
                    && bits & 0x0040_0000 == 0
            });
            let expected = if signaling || (nan && matches!(predicate, 1 | 2 | 5 | 6)) {
                generated | 1
            } else {
                generated
            };
            assert_eq!(
                snapshot.state.sse.as_ref().unwrap().mxcsr.get(),
                0x0180 | expected
            );
        }
    }

    let (input, baseline) = run(CMPSS_M32_MEMORY_RAX, "interpreter", 0);
    let mut wrong_result = baseline.clone();
    if let Observation::Available { value } = &mut wrong_result.snapshot {
        value.state.sse.as_mut().unwrap().xmm[0].replace_range(..8, "00000000");
    }
    assert!(od_testkit::v2::compare(&input, &wrong_result, &baseline).is_err());
    let mut wrong_status = baseline.clone();
    if let Observation::Available { value } = &mut wrong_status.snapshot {
        value.state.sse.as_mut().unwrap().mxcsr = HexU64(0x0181);
    }
    assert!(od_testkit::v2::compare(&input, &wrong_status, &baseline).is_err());
    let mut wrong_flags = baseline.clone();
    if let Observation::Available { value } = &mut wrong_flags.snapshot {
        value.state.rflags = HexU64(value.state.rflags.get() ^ 1);
    }
    assert!(od_testkit::v2::compare(&input, &wrong_flags, &baseline).is_err());

    let mut ac = fixture.clone();
    ac.case_id = "s2_37cs_ac1_unsupported".into();
    ac.initial_state.rflags = HexU64(ac.initial_state.rflags.get() | (1 << 18));
    ac.expected_exit = ExpectedExit::Unsupported;
    assert!(matches!(
        run(&ac.to_json().unwrap(), "interpreter", 4).1.outcome,
        Outcome::Unsupported { .. }
    ));
    for (index, controls) in [
        CmpssMemoryRaxControlSnapshot {
            sse_available: false,
            cr0_em: false,
            cr0_ts: true,
            cr4_osfxsr: true,
        },
        CmpssMemoryRaxControlSnapshot {
            sse_available: true,
            cr0_em: false,
            cr0_ts: true,
            cr4_osfxsr: true,
        },
    ]
    .into_iter()
    .enumerate()
    {
        let mut invalid_predicate = fixture.clone();
        invalid_predicate.case_id = format!("s2_37cs_predicate_8_precedes_gate_{index}");
        invalid_predicate.memory[0].initial_bytes_hex = "f30fc20008".into();
        invalid_predicate.memory[0].comparison_mask_hex = "ff".repeat(5);
        invalid_predicate.expected_exit = ExpectedExit::Unsupported;
        invalid_predicate.cmpss_memory_rax_controls = Some(controls);
        let (_, result) = run(&invalid_predicate.to_json().unwrap(), "interpreter", 4);
        assert!(matches!(result.outcome, Outcome::Unsupported { .. }));
    }
    for mxcsr in [0x0100, 0x0080, 0x01c0, 0x0040_0180] {
        let mut malformed = fixture.clone();
        malformed.initial_state.sse.as_mut().unwrap().mxcsr = HexU64(mxcsr);
        assert!(malformed.validate().is_err(), "accepted MXCSR {mxcsr:#x}");
    }
    let mut foreign = Fixture::from_json(CMPSS_REGISTER_PAIRS).unwrap().fixture;
    assert!(foreign.validate().is_ok());
    foreign.cmpss_memory_rax_controls = fixture.cmpss_memory_rax_controls;
    assert!(foreign.validate().is_err());
    assert!(Fixture::from_json(&serde_json::to_vec(&foreign).unwrap()).is_err());
    assert!(matches!(
        run(CMPSS_M32_MEMORY_RAX, "jit", 4).1.outcome,
        Outcome::Unsupported { .. }
    ));
    assert!(comparisons > 0);
}

#[test]
fn comisd_ucomisd_register_pairs_raw_u64_and_backend_denial() {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures/x86/stage2/s2_37w_comisd_ucomisd_baseline.case.json");
    let fixture = Fixture::from_json(&fs::read(path).unwrap())
        .unwrap()
        .fixture;
    let xmm = |raw: u64, high: u64| {
        let bytes = [raw.to_le_bytes(), high.to_le_bytes()].concat();
        bytes.iter().map(|b| format!("{b:02x}")).collect::<String>()
    };
    for opcode in [0x2f, 0x2e] {
        for destination in 0u8..16 {
            for source in 0u8..16 {
                let rex = match (destination >= 8, source >= 8) {
                    (false, false) => None,
                    (true, false) => Some(0x44),
                    (false, true) => Some(0x41),
                    (true, true) => Some(0x45),
                };
                let mut code = vec![0x66];
                if let Some(rex) = rex {
                    code.push(rex);
                }
                code.extend([0x0f, opcode, 0xc0 | ((destination & 7) << 3) | (source & 7)]);
                let mut case = fixture.clone();
                case.memory[0].initial_bytes_hex =
                    code.iter().map(|b| format!("{b:02x}")).collect();
                case.memory[0].length = code.len() as u32;
                case.memory[0].comparison_mask_hex = "ff".repeat(code.len());
                case.stop_rip = Some(HexU64(case.initial_state.rip.get() + code.len() as u64));
                case.case_id = format!("s2_37w_pair_{opcode:02x}_{destination}_{source}");
                let state = case.initial_state.sse.as_mut().unwrap();
                state.xmm = std::array::from_fn(|r| {
                    xmm(0x3ff0_0000_0000_0000 + r as u64, 0x7ff0_0000_0000_0001)
                });
                state.xmm[usize::from(destination)] =
                    xmm(0x3ff0_0000_0000_0000, 0x7ff0_0000_0000_0001);
                state.xmm[usize::from(source)] = xmm(0x4000_0000_0000_0000, 0x0000_0000_0000_0001);
                let (input, result) = run(&case.to_json().unwrap(), "interpreter", 0);
                od_testkit::v2::compare(&input, &result, &result).unwrap();
            }
        }
    }
    let classes = [
        0x0000_0000_0000_0000,
        0x8000_0000_0000_0000,
        0x3ff0_0000_0000_0000,
        0x3ff0_0000_0000_0001,
        0x000f_ffff_ffff_ffff,
        0x0000_0000_0000_0001,
        0x7ff0_0000_0000_0000,
        0xfff0_0000_0000_0000,
        0x7ff8_1234_5678_9abc,
        0xfff8_1234_5678_9abc,
        0x7ff0_1234_5678_9abc,
        0xfff0_0000_0000_0001,
    ];
    for opcode in [0x2f, 0x2e] {
        for (i, left) in classes.iter().copied().enumerate() {
            for (j, right) in classes.iter().copied().enumerate() {
                let mut case = fixture.clone();
                case.memory[0].initial_bytes_hex = format!("660f{opcode:02x}c1");
                case.memory[0].length = 4;
                case.memory[0].comparison_mask_hex = "ffffffff".into();
                case.stop_rip = Some(HexU64(case.initial_state.rip.get() + 4));
                case.case_id = format!("s2_37w_class_{opcode:02x}_{i}_{j}");
                let state = case.initial_state.sse.as_mut().unwrap();
                state.xmm[0] = xmm(left, 0x7ff0_0000_0000_0001);
                state.xmm[1] = xmm(right, 0x0000_0000_0000_0001);
                let (input, result) = run(&case.to_json().unwrap(), "interpreter", 0);
                od_testkit::v2::compare(&input, &result, &result).unwrap();
            }
        }
    }
    for bad in [
        vec![0x0f, 0x2f, 0xc1],
        vec![0x66, 0x40, 0x0f, 0x2f, 0xc1],
        vec![0x41, 0x66, 0x0f, 0x2f, 0xc1],
        vec![0x66, 0x66, 0x0f, 0x2f, 0xc1],
        vec![0x66, 0x48, 0x0f, 0x2f, 0xc1],
        vec![0x66, 0x0f, 0x2f, 0x01],
        vec![0x66, 0x0f, 0x2f, 0xc1, 0x90],
        vec![0xc5, 0xf9, 0x2f, 0xc1],
        vec![0x62, 0xf1, 0xfd, 0x08, 0x2f, 0xc1],
    ] {
        let mut bad_case = fixture.clone();
        bad_case.memory[0].initial_bytes_hex = bad.iter().map(|b| format!("{b:02x}")).collect();
        bad_case.memory[0].length = bad.len() as u32;
        bad_case.memory[0].comparison_mask_hex = "ff".repeat(bad.len());
        bad_case.stop_rip = Some(HexU64(bad_case.initial_state.rip.get() + bad.len() as u64));
        assert!(
            bad_case.validate().is_err(),
            "accepted malformed {bad:02x?}"
        );
    }
    for (lhs, rhs, opcode, unmask) in [
        (0x7ff8_1234_5678_9abc, 0x3ff0_0000_0000_0000, 0x2f, 7),
        (0x7ff0_1234_5678_9abc, 0x3ff0_0000_0000_0000, 0x2e, 7),
        (0x0000_0000_0000_0001, 0x3ff0_0000_0000_0000, 0x2f, 8),
    ] {
        let mut case = fixture.clone();
        case.memory[0].initial_bytes_hex = format!("660f{opcode:02x}c1");
        case.initial_state.sse.as_mut().unwrap().xmm[0] = xmm(lhs, 0);
        case.initial_state.sse.as_mut().unwrap().xmm[1] = xmm(rhs, 0);
        case.initial_state.sse.as_mut().unwrap().mxcsr = HexU64(0x1f80 & !(1 << unmask));
        case.initial_state.rflags = HexU64(0x8d7);
        case.expected_exit = ExpectedExit::Exception;
        let (input, result) = run(&case.to_json().unwrap(), "interpreter", 0);
        od_testkit::v2::compare(&input, &result, &result).unwrap();
        assert_eq!(snapshot(&result).state.rflags, case.initial_state.rflags);
    }
    let mut fault_case = fixture.clone();
    fault_case.initial_state.sse.as_mut().unwrap().xmm[0] = xmm(0x7ff8_1234_5678_9abc, 0);
    fault_case.initial_state.sse.as_mut().unwrap().mxcsr = HexU64(0x1f00);
    fault_case.expected_exit = ExpectedExit::Exception;
    let (fault_input, fault_result) = run(&fault_case.to_json().unwrap(), "interpreter", 0);
    od_testkit::v2::compare(&fault_input, &fault_result, &fault_result).unwrap();
    let mut fabricated_error_code = fault_result.clone();
    if let Observation::Available { value: snapshot } = &mut fabricated_error_code.snapshot {
        if let Observation::Available {
            value: Some(exception),
        } = &mut snapshot.exception
        {
            exception.error_code = Observation::Available { value: HexU64(0) };
        }
    }
    assert!(fabricated_error_code.validate_for(&fault_input).is_err());
    let mut fabricated_fault_address = fault_result.clone();
    if let Observation::Available { value: snapshot } = &mut fabricated_fault_address.snapshot {
        if let Observation::Available {
            value: Some(exception),
        } = &mut snapshot.exception
        {
            exception.fault_address = Observation::Available {
                value: HexU64(0x1000),
            };
        }
    }
    assert!(fabricated_fault_address.validate_for(&fault_input).is_err());
    for (sse2, em, osfxsr, ts) in [
        (false, false, true, true),
        (true, true, true, false),
        (true, false, false, false),
        (true, false, true, true),
    ] {
        let mut case = fixture.clone();
        let controls = case.comisd_ucomisd_controls.as_mut().unwrap();
        controls.sse2_available = sse2;
        controls.cr0_em = em;
        controls.cr4_osfxsr = osfxsr;
        controls.cr0_ts = ts;
        case.expected_exit = ExpectedExit::Exception;
        let (input, result) = run(&case.to_json().unwrap(), "interpreter", 0);
        od_testkit::v2::compare(&input, &result, &result).unwrap();
    }
    for mxcsr in [0x1fc0, 0x0001_0000] {
        let mut invalid = fixture.clone();
        invalid.initial_state.sse.as_mut().unwrap().mxcsr = HexU64(mxcsr);
        assert!(
            invalid.validate().is_err(),
            "accepted unsupported MXCSR {mxcsr:#x}"
        );
    }
    let (_, result) = run(&fixture.to_json().unwrap(), "jit", 4);
    assert!(matches!(result.outcome, Outcome::Unsupported { .. }));
    let (input, success) = run(&fixture.to_json().unwrap(), "interpreter", 0);
    let mut changed = success.clone();
    if let Observation::Available { value } = &mut changed.snapshot {
        value.state.rflags = HexU64(value.state.rflags.get() ^ 1);
    }
    assert!(od_testkit::v2::compare(&input, &success, &changed).is_err());
    let mut changed_controls = success.clone();
    if let Observation::Available { value } = &mut changed_controls.snapshot {
        value
            .comisd_ucomisd_controls
            .as_mut()
            .unwrap()
            .sse2_available = false;
    }
    assert!(od_testkit::v2::compare(&input, &success, &changed_controls).is_err());
}

#[test]
fn cmpss_register_pairs_predicates_raw_classes_exceptions_and_denial() {
    let fixture = Fixture::from_json(CMPSS_REGISTER_PAIRS).unwrap().fixture;
    let bytes32 = |value: u32| {
        value
            .to_le_bytes()
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>()
    };
    let xmm = |raw: u32, tail: u128| {
        format!(
            "{}{:024x}",
            bytes32(raw),
            tail & 0x00ff_ffff_ffff_ffff_ffff_ffff
        )
    };
    let set_code = |case: &mut Fixture, destination: u8, source: u8, predicate: u8| {
        let mut bytes = vec![0xf3];
        match (destination >= 8, source >= 8) {
            (false, false) => {}
            (true, false) => bytes.push(0x44),
            (false, true) => bytes.push(0x41),
            (true, true) => bytes.push(0x45),
        }
        bytes.extend([
            0x0f,
            0xc2,
            0xc0 | ((destination & 7) << 3) | (source & 7),
            predicate,
        ]);
        case.memory[0].initial_bytes_hex = bytes.iter().map(|byte| format!("{byte:02x}")).collect();
        case.memory[0].length = bytes.len() as u32;
        case.memory[0].comparison_mask_hex = "ff".repeat(bytes.len());
        case.stop_rip = Some(HexU64(case.initial_state.rip.get() + bytes.len() as u64));
        case.expected_exit = ExpectedExit::StopAddress;
    };
    let set_operands = |case: &mut Fixture, destination: u8, source: u8, lhs: u32, rhs: u32| {
        let sse = case.initial_state.sse.as_mut().unwrap();
        sse.xmm = std::array::from_fn(|index| xmm(0x3f00_0000 + index as u32, index as u128));
        sse.xmm[usize::from(destination)] = xmm(lhs, 0x1122_3344_5566_7788_99aa_bbcc);
        sse.xmm[usize::from(source)] = xmm(rhs, 0x8877_6655_4433_2211_aabb_ccdd);
        sse.mxcsr = HexU64(0x1f80);
    };
    let mut anchor = fixture.clone();
    set_code(&mut anchor, 0, 1, 1);
    set_operands(&mut anchor, 0, 1, 0x3f80_0000, 0x4000_0000);
    let (anchor_input, anchor_result) = run(&anchor.to_json().unwrap(), "interpreter", 0);
    od_testkit::v2::compare(&anchor_input, &anchor_result, &anchor_result).unwrap();
    let (_, jit) = run(&anchor.to_json().unwrap(), "jit", 4);
    assert!(matches!(jit.outcome, Outcome::Unsupported { .. }));
    let (_, native) = run(&anchor.to_json().unwrap(), "native", 4);
    assert!(matches!(native.outcome, Outcome::Unsupported { .. }));

    for destination in 0u8..16 {
        for source in 0u8..16 {
            for predicate in 0u8..8 {
                let mut case = fixture.clone();
                set_code(&mut case, destination, source, predicate);
                set_operands(&mut case, destination, source, 0x3f80_0000, 0x4000_0000);
                case.case_id = format!("s2_37x_pair_{destination}_{source}_{predicate}");
                let (input, result) = run(&case.to_json().unwrap(), "interpreter", 0);
                od_testkit::v2::compare(&input, &result, &result).unwrap();
            }
        }
    }

    let classes = [
        0,
        0x8000_0000,
        1,
        0x8000_0001,
        0x007f_ffff,
        0x807f_ffff,
        0x0080_0000,
        0x3f80_0000,
        0x3f80_0001,
        0xbf80_0000,
        0x7f80_0000,
        0xff80_0000,
        0x7fc1_2345,
        0xffc5_4321,
        0x7f81_2345,
        0xff80_0001,
    ];
    for (left_index, lhs) in classes.iter().copied().enumerate() {
        for (right_index, rhs) in classes.iter().copied().enumerate() {
            for predicate in 0u8..8 {
                let mut case = fixture.clone();
                set_code(&mut case, 0, 1, predicate);
                set_operands(&mut case, 0, 1, lhs, rhs);
                case.case_id = format!("s2_37x_class_{left_index}_{right_index}_{predicate}");
                let (input, result) = run(&case.to_json().unwrap(), "interpreter", 0);
                od_testkit::v2::compare(&input, &result, &result).unwrap();
            }
        }
    }

    for (pair_index, (lhs, rhs)) in [
        (0x7fc1_2345, 1), // QNaN outranks denormal even for a nonsignaling predicate.
        (0x7f81_2345, 1),
        (1, 0x3f80_0000),
    ]
    .into_iter()
    .enumerate()
    {
        for predicate in 0u8..8 {
            for im in [false, true] {
                for dm in [false, true] {
                    for osxmmexcpt in [false, true] {
                        for (old_ie, old_de) in
                            [(false, false), (true, false), (false, true), (true, true)]
                        {
                            let mut case = fixture.clone();
                            set_code(&mut case, 0, 1, predicate);
                            set_operands(&mut case, 0, 1, lhs, rhs);
                            let sse = case.initial_state.sse.as_mut().unwrap();
                            sse.mxcsr = HexU64(u64::from(
                                (0x1f80u32 & !0x180)
                                    | (u32::from(im) << 7)
                                    | (u32::from(dm) << 8)
                                    | u32::from(old_ie)
                                    | (u32::from(old_de) << 1),
                            ));
                            case.cmpss_controls.as_mut().unwrap().cr4_osxmmexcpt = osxmmexcpt;
                            let is_nan = |raw: u32| {
                                raw & 0x7f80_0000 == 0x7f80_0000 && raw & 0x007f_ffff != 0
                            };
                            let is_snan = |raw: u32| is_nan(raw) && raw & 0x0040_0000 == 0;
                            let unordered = is_nan(lhs) || is_nan(rhs);
                            let new_ie = is_snan(lhs)
                                || is_snan(rhs)
                                || (matches!(predicate, 1 | 2 | 5 | 6) && unordered);
                            let new_de = !unordered
                                && ((lhs & 0x7f80_0000 == 0 && lhs & 0x007f_ffff != 0)
                                    || (rhs & 0x7f80_0000 == 0 && rhs & 0x007f_ffff != 0));
                            case.expected_exit = if (new_ie && !im) || (new_de && !dm) {
                                ExpectedExit::Exception
                            } else {
                                ExpectedExit::StopAddress
                            };
                            case.case_id = format!(
                                "s2_37x_exc_{pair_index}_{predicate}_{im}_{dm}_{osxmmexcpt}_{old_ie}_{old_de}"
                            );
                            let (input, result) = run(&case.to_json().unwrap(), "interpreter", 0);
                            od_testkit::v2::compare(&input, &result, &result).unwrap();
                        }
                    }
                }
            }
        }
    }

    let mut fault = fixture.clone();
    set_code(&mut fault, 0, 1, 0);
    set_operands(&mut fault, 0, 1, 0x7f81_2345, 0x3f80_0000);
    fault.initial_state.sse.as_mut().unwrap().mxcsr = HexU64(0x1f00);
    fault.expected_exit = ExpectedExit::Exception;
    let (fault_input, fault_result) = run(&fault.to_json().unwrap(), "interpreter", 0);
    od_testkit::v2::compare(&fault_input, &fault_result, &fault_result).unwrap();
    let mut fabricated_error_code = fault_result.clone();
    if let Observation::Available { value: snapshot } = &mut fabricated_error_code.snapshot
        && let Observation::Available {
            value: Some(exception),
        } = &mut snapshot.exception
    {
        exception.error_code = Observation::Available { value: HexU64(0) };
    }
    assert!(fabricated_error_code.validate_for(&fault_input).is_err());
    let mut fabricated_fault_address = fault_result.clone();
    if let Observation::Available { value: snapshot } = &mut fabricated_fault_address.snapshot
        && let Observation::Available {
            value: Some(exception),
        } = &mut snapshot.exception
    {
        exception.fault_address = Observation::Available {
            value: HexU64(0x1000),
        };
    }
    assert!(fabricated_fault_address.validate_for(&fault_input).is_err());

    for bad in [
        vec![0xf3, 0x0f, 0xc2, 0xc1, 0x08],
        vec![0xf3, 0x0f, 0xc2, 0xc1, 0x80],
        vec![0xf3, 0x0f, 0xc2, 0x01, 0],
        vec![0xf3, 0x40, 0x0f, 0xc2, 0xc1, 0],
        vec![0xf3, 0x48, 0x0f, 0xc2, 0xc1, 0],
        vec![0xf3, 0x42, 0x0f, 0xc2, 0xc1, 0],
        vec![0xf3, 0xf3, 0x0f, 0xc2, 0xc1, 0],
        vec![0xf2, 0x0f, 0xc2, 0xc1, 0],
        vec![0x66, 0xf3, 0x0f, 0xc2, 0xc1, 0],
        vec![0xf3, 0x0f, 0xc2, 0xc1, 0, 0x90],
        vec![0xc5, 0xf8, 0xc2, 0xc1, 0],
        vec![0x62, 0xf1, 0x7c, 0x08, 0xc2, 0xc1, 0],
    ] {
        let mut malformed = fixture.clone();
        malformed.memory[0].initial_bytes_hex =
            bad.iter().map(|byte| format!("{byte:02x}")).collect();
        malformed.memory[0].length = bad.len() as u32;
        malformed.memory[0].comparison_mask_hex = "ff".repeat(bad.len());
        malformed.stop_rip = Some(HexU64(malformed.initial_state.rip.get() + bad.len() as u64));
        assert!(
            malformed.to_json().is_err(),
            "accepted malformed form {bad:02x?}"
        );
    }
    let mut wrong_control = fixture.clone();
    wrong_control.comiss_ucomiss_controls = Some(ComissUcomissControlSnapshot {
        sse_available: true,
        cr0_em: false,
        cr0_ts: false,
        cr4_osfxsr: true,
        cr4_osxmmexcpt: true,
    });
    assert!(wrong_control.to_json().is_err());
}

#[test]
fn cmpsd_register_pairs_predicates_raw_classes_exceptions_and_denial() {
    let fixture = Fixture::from_json(CMPSD_REGISTER_PAIRS).unwrap().fixture;
    let bytes64 = |value: u64| {
        value
            .to_le_bytes()
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>()
    };
    let xmm =
        |raw: u64, tail: u128| format!("{}{:016x}", bytes64(raw), tail & 0xffff_ffff_ffff_ffff);
    let set_code = |case: &mut Fixture, destination: u8, source: u8, predicate: u8| {
        let mut bytes = vec![0xf2];
        match (destination >= 8, source >= 8) {
            (false, false) => {}
            (true, false) => bytes.push(0x44),
            (false, true) => bytes.push(0x41),
            (true, true) => bytes.push(0x45),
        }
        bytes.extend([
            0x0f,
            0xc2,
            0xc0 | ((destination & 7) << 3) | (source & 7),
            predicate,
        ]);
        case.memory[0].initial_bytes_hex = bytes.iter().map(|byte| format!("{byte:02x}")).collect();
        case.memory[0].length = bytes.len() as u32;
        case.memory[0].comparison_mask_hex = "ff".repeat(bytes.len());
        case.stop_rip = Some(HexU64(case.initial_state.rip.get() + bytes.len() as u64));
        case.expected_exit = ExpectedExit::StopAddress;
    };
    let set_operands = |case: &mut Fixture, destination: u8, source: u8, lhs: u64, rhs: u64| {
        let sse = case.initial_state.sse.as_mut().unwrap();
        sse.xmm =
            std::array::from_fn(|index| xmm(0x3ff0_0000_0000_0000 + index as u64, index as u128));
        sse.xmm[usize::from(destination)] = xmm(lhs, 0x1122_3344_5566_7788_99aa_bbcc);
        sse.xmm[usize::from(source)] = xmm(rhs, 0x8877_6655_4433_2211_aabb_ccdd);
        sse.mxcsr = HexU64(0x1f80);
    };
    let mut anchor = fixture.clone();
    set_code(&mut anchor, 0, 1, 1);
    set_operands(
        &mut anchor,
        0,
        1,
        0x3ff0_0000_0000_0000,
        0x4000_0000_0000_0000,
    );
    let (anchor_input, anchor_result) = run(&anchor.to_json().unwrap(), "interpreter", 0);
    od_testkit::v2::compare(&anchor_input, &anchor_result, &anchor_result).unwrap();
    let (_, jit) = run(&anchor.to_json().unwrap(), "jit", 4);
    assert!(matches!(jit.outcome, Outcome::Unsupported { .. }));
    let (_, native) = run(&anchor.to_json().unwrap(), "native", 4);
    assert!(matches!(native.outcome, Outcome::Unsupported { .. }));

    // Binary64's quiet bit is fraction bit 51. QNaN is quiet for predicate 0;
    // SNaN raises IE regardless of predicate.
    for (raw, expected_ie, case_name) in [
        (0x7ff8000000000001, 0, "qnan_quiet"),
        (0x7ff0000000000001, 1, "snan_signaling"),
    ] {
        let mut case = fixture.clone();
        set_code(&mut case, 0, 1, 0);
        set_operands(&mut case, 0, 1, raw, 0x3ff0_0000_0000_0000);
        case.case_id = format!("s2_37y_binary64_{case_name}");
        let (input, result) = run(&case.to_json().unwrap(), "interpreter", 0);
        od_testkit::v2::compare(&input, &result, &result).unwrap();
        assert_eq!(
            snapshot(&result).state.sse.as_ref().unwrap().mxcsr.get() & 1,
            expected_ie
        );
    }

    for destination in 0u8..16 {
        for source in 0u8..16 {
            for predicate in 0u8..8 {
                let mut case = fixture.clone();
                set_code(&mut case, destination, source, predicate);
                set_operands(
                    &mut case,
                    destination,
                    source,
                    0x3ff0_0000_0000_0000,
                    0x4000_0000_0000_0000,
                );
                case.case_id = format!("s2_37y_pair_{destination}_{source}_{predicate}");
                let (input, result) = run(&case.to_json().unwrap(), "interpreter", 0);
                od_testkit::v2::compare(&input, &result, &result).unwrap();
            }
        }
    }

    let classes: [u64; 16] = [
        0,
        0x8000_0000_0000_0000,
        1,
        0x8000_0000_0000_0001,
        0x000f_ffff_ffff_ffff,
        0x800f_ffff_ffff_ffff,
        0x0010_0000_0000_0000,
        0x3ff0_0000_0000_0000,
        0x3ff0_0000_0000_0001,
        0xbff0_0000_0000_0000,
        0x7ff0_0000_0000_0000,
        0xfff0_0000_0000_0000,
        0x7ff8_0000_0000_1234,
        0xfff8_0000_0000_4321,
        0x7ff0_0000_0000_0001,
        0xfff0_0000_0000_0001,
    ];
    for (left_index, lhs) in classes.iter().copied().enumerate() {
        for (right_index, rhs) in classes.iter().copied().enumerate() {
            for predicate in 0u8..8 {
                let mut case = fixture.clone();
                set_code(&mut case, 0, 1, predicate);
                set_operands(&mut case, 0, 1, lhs, rhs);
                case.case_id = format!("s2_37y_class_{left_index}_{right_index}_{predicate}");
                let (input, result) = run(&case.to_json().unwrap(), "interpreter", 0);
                od_testkit::v2::compare(&input, &result, &result).unwrap();
            }
        }
    }

    // All rounding modes and FTZ settings are admitted and do not change a compare.
    for rc in 0u32..4 {
        for ftz in [false, true] {
            let mut case = fixture.clone();
            set_code(&mut case, 0, 1, 2);
            set_operands(&mut case, 0, 1, 1, 0x3ff0_0000_0000_0000);
            case.initial_state.sse.as_mut().unwrap().mxcsr =
                HexU64(u64::from(0x1f80u32 | (rc << 13) | (u32::from(ftz) << 15)));
            case.case_id = format!("s2_37y_rc_ftz_{rc}_{ftz}");
            let (input, result) = run(&case.to_json().unwrap(), "interpreter", 0);
            od_testkit::v2::compare(&input, &result, &result).unwrap();
        }
    }

    for (pair_index, (lhs, rhs)) in [
        (0x7ff8_0000_0000_0001, 1), // QNaN outranks denormal even for a nonsignaling predicate.
        (0x7ff0_0000_0000_0001, 1),
        (1, 0x3ff0_0000_0000_0000),
    ]
    .into_iter()
    .enumerate()
    {
        for predicate in 0u8..8 {
            for im in [false, true] {
                for dm in [false, true] {
                    for osxmmexcpt in [false, true] {
                        for (old_ie, old_de) in
                            [(false, false), (true, false), (false, true), (true, true)]
                        {
                            let mut case = fixture.clone();
                            set_code(&mut case, 0, 1, predicate);
                            set_operands(&mut case, 0, 1, lhs, rhs);
                            let sse = case.initial_state.sse.as_mut().unwrap();
                            sse.mxcsr = HexU64(u64::from(
                                (0x1f80u64 & !0x180)
                                    | (u64::from(im) << 7)
                                    | (u64::from(dm) << 8)
                                    | u64::from(old_ie)
                                    | (u64::from(old_de) << 1),
                            ));
                            case.cmpsd_controls.as_mut().unwrap().cr4_osxmmexcpt = osxmmexcpt;
                            let is_nan = |raw: u64| {
                                raw & 0x7ff0_0000_0000_0000 == 0x7ff0_0000_0000_0000
                                    && raw & 0x000f_ffff_ffff_ffff != 0
                            };
                            let is_snan =
                                |raw: u64| is_nan(raw) && raw & 0x0008_0000_0000_0000 == 0;
                            let unordered = is_nan(lhs) || is_nan(rhs);
                            let new_ie = is_snan(lhs)
                                || is_snan(rhs)
                                || (matches!(predicate, 1 | 2 | 5 | 6) && unordered);
                            let new_de = !unordered
                                && ((lhs & 0x7ff0_0000_0000_0000 == 0
                                    && lhs & 0x000f_ffff_ffff_ffff != 0)
                                    || (rhs & 0x7ff0_0000_0000_0000 == 0
                                        && rhs & 0x000f_ffff_ffff_ffff != 0));
                            case.expected_exit = if (new_ie && !im) || (new_de && !dm) {
                                ExpectedExit::Exception
                            } else {
                                ExpectedExit::StopAddress
                            };
                            case.case_id = format!(
                                "s2_37y_exc_{pair_index}_{predicate}_{im}_{dm}_{osxmmexcpt}_{old_ie}_{old_de}"
                            );
                            let (input, result) = run(&case.to_json().unwrap(), "interpreter", 0);
                            od_testkit::v2::compare(&input, &result, &result).unwrap();
                        }
                    }
                }
            }
        }
    }

    let mut fault = fixture.clone();
    set_code(&mut fault, 0, 1, 0);
    set_operands(
        &mut fault,
        0,
        1,
        0x7ff0_0000_0000_0001,
        0x3ff0_0000_0000_0000,
    );
    fault.initial_state.sse.as_mut().unwrap().mxcsr = HexU64(0x1f00);
    fault.expected_exit = ExpectedExit::Exception;
    let (fault_input, fault_result) = run(&fault.to_json().unwrap(), "interpreter", 0);
    od_testkit::v2::compare(&fault_input, &fault_result, &fault_result).unwrap();
    let mut fabricated_error_code = fault_result.clone();
    if let Observation::Available { value: snapshot } = &mut fabricated_error_code.snapshot
        && let Observation::Available {
            value: Some(exception),
        } = &mut snapshot.exception
    {
        exception.error_code = Observation::Available { value: HexU64(0) };
    }
    assert!(fabricated_error_code.validate_for(&fault_input).is_err());
    let mut fabricated_fault_address = fault_result.clone();
    if let Observation::Available { value: snapshot } = &mut fabricated_fault_address.snapshot
        && let Observation::Available {
            value: Some(exception),
        } = &mut snapshot.exception
    {
        exception.fault_address = Observation::Available {
            value: HexU64(0x1000),
        };
    }
    assert!(fabricated_fault_address.validate_for(&fault_input).is_err());

    for bad in [
        vec![0xf2, 0x0f, 0xc2, 0xc1, 0x08],
        vec![0xf2, 0x0f, 0xc2, 0xc1, 0x80],
        vec![0xf2, 0x0f, 0xc2, 0x01, 0],
        vec![0xf2, 0x40, 0x0f, 0xc2, 0xc1, 0],
        vec![0xf2, 0x48, 0x0f, 0xc2, 0xc1, 0],
        vec![0xf2, 0x42, 0x0f, 0xc2, 0xc1, 0],
        vec![0xf2, 0xf3, 0x0f, 0xc2, 0xc1, 0],
        vec![0xf3, 0x0f, 0xc2, 0xc1, 0],
        vec![0x66, 0xf2, 0x0f, 0xc2, 0xc1, 0],
        vec![0xf2, 0x0f, 0xc2, 0xc1, 0, 0x90],
        vec![0xc5, 0xf8, 0xc2, 0xc1, 0],
        vec![0x62, 0xf1, 0x7c, 0x08, 0xc2, 0xc1, 0],
    ] {
        let mut malformed = fixture.clone();
        malformed.memory[0].initial_bytes_hex =
            bad.iter().map(|byte| format!("{byte:02x}")).collect();
        malformed.memory[0].length = bad.len() as u32;
        malformed.memory[0].comparison_mask_hex = "ff".repeat(bad.len());
        malformed.stop_rip = Some(HexU64(malformed.initial_state.rip.get() + bad.len() as u64));
        assert!(
            malformed.to_json().is_err(),
            "accepted malformed form {bad:02x?}"
        );
    }
    let mut wrong_control = fixture.clone();
    wrong_control.cmpss_controls = Some(od_testkit::v2::CmpssControlSnapshot {
        sse_available: true,
        cr0_em: false,
        cr0_ts: false,
        cr4_osfxsr: true,
        cr4_osxmmexcpt: true,
    });
    assert!(wrong_control.to_json().is_err());

    let mut daz = fixture.clone();
    daz.initial_state.sse.as_mut().unwrap().mxcsr = HexU64(0x1fc0);
    assert!(daz.to_json().is_err());
    let mut reserved_mxcsr = fixture.clone();
    reserved_mxcsr.initial_state.sse.as_mut().unwrap().mxcsr = HexU64(0x20000);
    assert!(reserved_mxcsr.to_json().is_err());
}

